            FROM prestamos p
            JOIN libros l ON l.id = p.id_libro
            WHERE (? IS NULL OR DATE(p.fecha_prestamo) BETWEEN ? AND ?)
            GROUP BY p.id_libro
            ORDER BY total_solicitudes DESC
