        } catch (SQLException e) {
            Alertas.mostrarError("Error al obtener resumen de plataforma por docente: " + e.getMessage());
        } finally {
            ConexionSQLite.cerrarConexion();
        }

        return resumen;
    }

    public List<InventarioLibroDetalle> obtenerInventarioParaCompra(int umbralStock) {
        String query = """
            SELECT
                l.id,
                l.titulo,
                COALESCE(c.nombre_categoria, 'Sin categoria') AS categoria,
                COALESCE(l.autor, 'N/A') AS autor,
                COALESCE(l.editorial, 'N/A') AS editorial,
                COALESCE(l.ubicacion, 'N/A') AS ubicacion,
                COALESCE(l.unidades, 0) AS unidades,
                COALESCE(pa.prestamos_activos, 0) AS prestamos_activos,
                COALESCE(ph.prestamos_historicos, 0) AS prestamos_historicos
            FROM libros l
            LEFT JOIN categorias c ON c.id = l.id_categoria
            LEFT JOIN (
                SELECT p.id_libro, COUNT(*) AS prestamos_activos
                FROM prestamos p
                WHERE p.estado IN (0, 2)
                GROUP BY p.id_libro
            ) pa ON pa.id_libro = l.id
            LEFT JOIN (
                SELECT p.id_libro, COUNT(*) AS prestamos_historicos
                FROM prestamos p
                GROUP BY p.id_libro
            ) ph ON ph.id_libro = l.id
            ORDER BY l.titulo ASC
        """;

        List<InventarioLibroDetalle> inventario = new ArrayList<>();

        try (Connection conexion = ConexionSQLite.conectar();
             PreparedStatement ps = conexion.prepareStatement(query);
             ResultSet rs = ps.executeQuery()) {

            int umbralSeguro = Math.max(1, umbralStock);
            while (rs.next()) {
                int unidades = rs.getInt("unidades");
                int prestamosActivos = rs.getInt("prestamos_activos");
                int stockObjetivo = umbralSeguro + prestamosActivos;
                int recomendadasComprar = Math.max(0, stockObjetivo - unidades);

                inventario.add(new InventarioLibroDetalle(
                        rs.getInt("id"),
                        rs.getString("titulo"),
                        rs.getString("categoria"),
                        rs.getString("autor"),
                        rs.getString("editorial"),
                        rs.getString("ubicacion"),
                        unidades,
                        prestamosActivos,
                        rs.getInt("prestamos_historicos"),
                        stockObjetivo,
                        recomendadasComprar
                ));
            }
        } catch (SQLException e) {
            Alertas.mostrarError("Error al obtener inventario para compra: " + e.getMessage());
        } finally {
            ConexionSQLite.cerrarConexion();
        }

        inventario.sort((a, b) -> {
            int porRecomendadas = Integer.compare(b.getRecomendadasComprar(), a.getRecomendadasComprar());
            if (porRecomendadas != 0) {
                return porRecomendadas;
            }
            int porUnidades = Integer.compare(a.getUnidades(), b.getUnidades());
            if (porUnidades != 0) {
                return porUnidades;
            }
            return b.getPrestamosHistoricos() - a.getPrestamosHistoricos();
        });

        return inventario;
    }

    public Map<String, Object> obtenerResumenInventario(int umbralStock) {
        Map<String, Object> resumen = new HashMap<>();
        List<InventarioLibroDetalle> inventario = obtenerInventarioParaCompra(umbralStock);

        int totalTitulos = inventario.size();
        int totalUnidades = inventario.stream().mapToInt(InventarioLibroDetalle::getUnidades).sum();
        int totalPrestamosActivos = inventario.stream().mapToInt(InventarioLibroDetalle::getPrestamosActivos).sum();
        int totalSugeridasCompra = inventario.stream().mapToInt(InventarioLibroDetalle::getRecomendadasComprar).sum();
        long titulosConRiesgo = inventario.stream().filter(i -> i.getRecomendadasComprar() > 0).count();

        resumen.put("totalTitulos", totalTitulos);
        resumen.put("totalUnidades", totalUnidades);
        resumen.put("totalPrestamosActivos", totalPrestamosActivos);
        resumen.put("totalSugeridasCompra", totalSugeridasCompra);
        resumen.put("titulosConRiesgo", titulosConRiesgo);
        resumen.put("libroMasCritico", inventario.isEmpty() ? "Sin datos" : inventario.get(0).getTitulo());

        return resumen;
    }

    private int setFiltroFecha(PreparedStatement ps, int start, String fechaInicio, String fechaFin) throws SQLException {
        ps.setString(start, fechaInicio);
        ps.setString(start + 1, fechaInicio);
        ps.setString(start + 2, fechaFin);
        return start + 3;
    }

    private RegistroPlataformaDetalle mapearRegistroPlataforma(ResultSet rs) throws SQLException {
        return new RegistroPlataformaDetalle(
                rs.getInt("id"),
                rs.getInt("id_docente"),
                rs.getString("docente"),
                rs.getString("motivo_uso"),
                rs.getString("fecha"),
                rs.getString("hora_inicio"),
                rs.getString("hora_fin"),
                rs.getInt("total_minutos"),
                rs.getInt("grado")
        );
    }

    private Prestamo mapearPrestamo(ResultSet rs, int idDocente, int idMotivo) throws SQLException {
        Prestamo prestamo = new Prestamo(
                rs.getInt("id"),
                rs.getInt("id_libro"),
                rs.getString("estudiante"),
                rs.getString("fecha_prestamo"),
                rs.getString("fecha_limite"),
                rs.getInt("estado"),
                rs.getInt("grado"),
                rs.getString("titulo"),
                obtenerDocentePorId(idDocente),
                obtenerMotivoPorId(idMotivo)
        );
        prestamo.setFecha_devolucion(rs.getString("fecha_devolucion"));
        prestamo.setDevuelto_tarde(rs.getInt("devuelto_tarde"));
        prestamo.setDias_atraso(rs.getInt("dias_atraso"));
        return prestamo;
    }

    // Métodos auxiliares privados
    private model.Docente obtenerDocentePorId(int idDocente) {
        String query = "SELECT id, nombre_1, nombre_2, apellido_1, apellido_2 FROM docentes WHERE id = ?";
        try (Connection conexion = ConexionSQLite.conectar();
             PreparedStatement ps = conexion.prepareStatement(query)) {

            ps.setInt(1, idDocente);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return new model.Docente(
                            rs.getInt("id"),
                            rs.getString("nombre_1"),
                            rs.getString("nombre_2"),
                            rs.getString("apellido_1"),
                            rs.getString("apellido_2")
                    );
                }
            }
        } catch (SQLException e) {
            Alertas.mostrarError("Error al obtener docente: " + e.getMessage());
        } finally {
            ConexionSQLite.cerrarConexion();
        }
        return null;
    }

    private model.MotivoPrestamo obtenerMotivoPorId(int idMotivo) {
        String query = "SELECT id, nombre_motivo FROM motivos_prestamo WHERE id = ?";
        try (Connection conexion = ConexionSQLite.conectar();
             PreparedStatement ps = conexion.prepareStatement(query)) {

            ps.setInt(1, idMotivo);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return new model.MotivoPrestamo(
                            rs.getInt("id"),
                            rs.getString("nombre_motivo")
                    );
                }
            }
        } catch (SQLException e) {
            Alertas.mostrarError("Error al obtener motivo: " + e.getMessage());
        } finally {
            ConexionSQLite.cerrarConexion();
        }
        return null;
    }
}

package model;

/**
 * DTO para el informe de inventario con foco en reposicion de libros.
 */
public class InventarioLibroDetalle {

    private final int idLibro;
    private final String titulo;
    private final String categoria;
    private final String autor;
    private final String editorial;
    private final String ubicacion;
    private final int unidades;
    private final int prestamosActivos;
    private final int prestamosHistoricos;
    private final int stockObjetivo;
    private final int recomendadasComprar;

    public InventarioLibroDetalle(
            int idLibro,
            String titulo,
            String categoria,
            String autor,
            String editorial,
            String ubicacion,
            int unidades,
            int prestamosActivos,
            int prestamosHistoricos,
            int stockObjetivo,
            int recomendadasComprar
    ) {
        this.idLibro = idLibro;
        this.titulo = titulo;
        this.categoria = categoria;
        this.autor = autor;
        this.editorial = editorial;
        this.ubicacion = ubicacion;
        this.unidades = unidades;
        this.prestamosActivos = prestamosActivos;
        this.prestamosHistoricos = prestamosHistoricos;
        this.stockObjetivo = stockObjetivo;
        this.recomendadasComprar = recomendadasComprar;
    }

    public int getIdLibro() {
        return idLibro;
    }

    public String getTitulo() {
        return titulo;
    }

    public String getCategoria() {
        return categoria;
    }

    public String getAutor() {
        return autor;
    }

    public String getEditorial() {
        return editorial;
    }

    public String getUbicacion() {
        return ubicacion;
    }

    public int getUnidades() {
        return unidades;
    }

    public int getPrestamosActivos() {
        return prestamosActivos;
    }

    public int getPrestamosHistoricos() {
        return prestamosHistoricos;
    }

    public int getStockObjetivo() {
        return stockObjetivo;
    }

    public int getRecomendadasComprar() {
        return recomendadasComprar;
    }

    public String getEstadoStock() {
        if (recomendadasComprar >= 3 || unidades <= 1) {
            return "Critico";
        }
        if (recomendadasComprar > 0) {
            return "Bajo";
        }
        return "Adecuado";
    }
}

package reports.generators;

import com.itextpdf.layout.element.Table;
import database.InformesDAO;
import model.InventarioLibroDetalle;
import reports.models.ReportConfig;
import utils.Alertas;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

/**
 * Generador de reporte de inventario con enfoque descriptivo.
 */
public class InventarioReportGenerator extends BaseReportGenerator {

    private final InformesDAO informesDAO;
    private final int umbralStock;

    public InventarioReportGenerator(ReportConfig config, int umbralStock) {
        super(config, "Reporte_Inventario_Libros.pdf");
        this.informesDAO = new InformesDAO();
        this.umbralStock = Math.max(1, umbralStock);
    }

    @Override
    public void generar() {
        if (!puedeGenerar()) {
            return;
        }

        try {
            agregarEncabezadoEstandar("Reporte de Inventario de Libros");
            agregarResumen();

            if (config.isIncluirTablas()) {
                agregarTablaDetalle();
            } else {
                pdfBuilder
                        .agregarSeccion("Detalle del inventario")
                        .agregarParrafoIndentado("No se incluyo la tabla detallada por decision del usuario.")
                        .agregarEspacio(8);
            }

            finalizarReporte();
            Alertas.mostrarExito("Reporte generado correctamente en:\n" + rutaArchivo);
        } catch (Exception e) {
            Alertas.mostrarError("Error al generar reporte de inventario: " + e.getMessage());
        }
    }

    private void agregarResumen() {
        List<InventarioLibroDetalle> inventario = informesDAO.obtenerInventarioParaCompra(umbralStock);
        int totalTitulos = inventario.size();
        int totalUnidades = inventario.stream().mapToInt(InventarioLibroDetalle::getUnidades).sum();
        int totalPrestamosActivos = inventario.stream().mapToInt(InventarioLibroDetalle::getPrestamosActivos).sum();
        long librosSinUnidades = inventario.stream().filter(item -> item.getUnidades() == 0).count();
        int menorStock = inventario.stream().mapToInt(InventarioLibroDetalle::getUnidades).min().orElse(0);

        pdfBuilder
                .agregarSeccion("Corte del reporte")
                .agregarLineaDetalle("Fecha de generacion", String.valueOf(LocalDate.now()))
                .agregarParrafoIndentado("Vista descriptiva del inventario actual de libros.")
                .agregarSeccion("Resumen")
                .agregarLineaDetalle("Titulos registrados", String.valueOf(totalTitulos))
                .agregarLineaDetalle("Unidades totales actuales", String.valueOf(totalUnidades))
                .agregarLineaDetalle("Prestamos activos", String.valueOf(totalPrestamosActivos))
                .agregarLineaDetalle("Libros sin unidades", String.valueOf(librosSinUnidades))
                .agregarLineaDetalle("Menor stock detectado", String.valueOf(menorStock) + " unidades")
                .agregarEspacio(12);

        agregarTop10MenosUnidades();
        agregarTop10MasSolicitados();
    }

    private void agregarTop10MenosUnidades() {
        List<InventarioLibroDetalle> topMenosUnidades = informesDAO.obtenerInventarioParaCompra(umbralStock)
                .stream()
                .sorted(Comparator
                        .comparingInt(InventarioLibroDetalle::getUnidades)
                        .thenComparing(Comparator.comparingInt(InventarioLibroDetalle::getPrestamosHistoricos).reversed())
                        .thenComparing(InventarioLibroDetalle::getTitulo, String.CASE_INSENSITIVE_ORDER))
                .limit(10)
                .toList();

        if (topMenosUnidades.isEmpty()) {
            return;
        }

        pdfBuilder.agregarSeccion("Top 10 libros con menos unidades");
        String[] encabezados = {"#", "Libro", "Categoria", "Unidades", "Prestamos activos"};
        float[] anchos = {0.5f, 3.4f, 1.8f, 0.9f, 1.2f};
        Table tabla = pdfBuilder.crearTabla(anchos, encabezados);

        int posicion = 1;
        for (InventarioLibroDetalle libro : topMenosUnidades) {
            String[] fila = {
                    String.valueOf(posicion++),
                    libro.getTitulo(),
                    libro.getCategoria(),
                    String.valueOf(libro.getUnidades()),
                    String.valueOf(libro.getPrestamosActivos())
            };
            pdfBuilder.agregarFilaTabla(tabla, fila);
        }
        pdfBuilder.agregarTabla(tabla).agregarEspacio(8);
    }

    private void agregarTop10MasSolicitados() {
        List<Map<String, Object>> topSolicitados = informesDAO.obtenerTopLibrosDetalle(null, null, 10);
        if (topSolicitados.isEmpty()) {
            return;
        }

        pdfBuilder.agregarSeccion("Top 10 libros mas solicitados");
        String[] encabezados = {"#", "Libro", "Solicitudes", "Estudiantes", "Grado frecuente"};
        float[] anchos = {0.5f, 3.4f, 1.0f, 1.0f, 1.2f};
        Table tabla = pdfBuilder.crearTabla(anchos, encabezados);

        int posicion = 1;
        for (Map<String, Object> filaTop : topSolicitados) {
            String[] fila = {
                    String.valueOf(posicion++),
                    String.valueOf(filaTop.getOrDefault("libro", "N/A")),
                    String.valueOf(filaTop.getOrDefault("total_solicitudes", 0)),
                    String.valueOf(filaTop.getOrDefault("estudiantes_unicos", 0)),
                    String.valueOf(filaTop.getOrDefault("grado_frecuente", "N/A"))
            };
            pdfBuilder.agregarFilaTabla(tabla, fila);
        }
        pdfBuilder.agregarTabla(tabla).agregarEspacio(8);
    }

    private void agregarTablaDetalle() {
        List<InventarioLibroDetalle> inventario = informesDAO.obtenerInventarioParaCompra(umbralStock);

        if (inventario.isEmpty()) {
            pdfBuilder.agregarParrafoIndentado("No se encontraron libros en inventario.");
            return;
        }

        pdfBuilder.agregarSeccion("Detalle del inventario");

        String[] encabezados = {
                "Libro", "Categoria", "Unidades", "Prestamos activos", "Stock objetivo", "Comprar", "Estado"
        };
        float[] anchos = {2.8f, 1.8f, 0.9f, 1.1f, 1.1f, 0.9f, 1.2f};
        Table tabla = pdfBuilder.crearTabla(anchos, encabezados);

        for (InventarioLibroDetalle item : inventario) {
            String[] fila = {
                    item.getTitulo(),
                    item.getCategoria(),
                    String.valueOf(item.getUnidades()),
                    String.valueOf(item.getPrestamosActivos()),
                    String.valueOf(item.getStockObjetivo()),
                    String.valueOf(item.getRecomendadasComprar()),
                    item.getEstadoStock()
            };
            pdfBuilder.agregarFilaTabla(tabla, fila);
        }

        pdfBuilder.agregarTabla(tabla);
    }
}
